/// offer to transfer data
pub const wl_data_offer = struct {
  pub const NAME = "wl_data_offer";
  pub const VERSION = 4;
  pub const INTERFACE: Interface = .wl_data_offer;
  pub const Id = enum(u32) { none = 0, _ };

  pub const Error = enum(u32) {
    /// finish request was called untimely
    invalid_finish = 0,
    /// action mask contains invalid values
    invalid_action_mask = 1,
    /// action argument has an invalid value
    invalid_action = 2,
    /// offer doesn't accept this request
    invalid_offer = 3,
    _,
  };

  /// accept one of the offered mime types
  pub fn accept(conn: *wire.Connection, self: Id, serial: u32, mime_type: ?[]const u8) wire.Error!void {
    const message_size  = 12 + wire.string_size(mime_type);
    const message_start = try conn.message_begin(@intFromEnum(self), 0, message_size, 0);
    conn.put_uint(serial);
    conn.put_string(mime_type);
    conn.message_end(message_start);
  }

  /// request that the data is transferred
  pub fn receive(
    conn: *wire.Connection,
    self: Id,
    mime_type: []const u8,
    fd: std.os.linux.fd_t,
  ) wire.Error!void {
    const message_size  = 8 + wire.string_size(mime_type);
    const message_start = try conn.message_begin(@intFromEnum(self), 1, message_size, 1);
    conn.put_string(mime_type);
    conn.put_fd(fd);
    conn.message_end(message_start);
  }

  /// destroy data offer
  pub fn destroy(conn: *wire.Connection, self: Id) wire.Error!void {
    const message_size  = 8;
    const message_start = try conn.message_begin(@intFromEnum(self), 2, message_size, 0);
    conn.message_end(message_start);
    conn.object_destroy(@intFromEnum(self));
  }

  /// the offer will no longer be used
  pub fn finish(conn: *wire.Connection, self: Id) wire.Error!void {
    const message_size  = 8;
    const message_start = try conn.message_begin(@intFromEnum(self), 3, message_size, 0);
    conn.message_end(message_start);
  }

  /// set the available/preferred drag-and-drop actions
  pub fn set_actions(
    conn: *wire.Connection,
    self: Id,
    dnd_actions: wl_data_device_manager.DndAction,
    preferred_action: wl_data_device_manager.DndAction,
  ) wire.Error!void {
    const message_size  = 16;
    const message_start = try conn.message_begin(@intFromEnum(self), 4, message_size, 0);
    conn.put_uint(@bitCast(dnd_actions));
    conn.put_uint(@bitCast(preferred_action));
    conn.message_end(message_start);
  }

  pub const EventOpcode = enum(u16) {
    offer          = 0,
    source_actions = 1,
    action         = 2,
  };

  pub const Event = union(EventOpcode) {
    offer: Event.Offer,
    source_actions: Event.SourceActions,
    action: Event.Action,

    /// advertise offered mime type
    pub const Offer = struct {
      mime_type: []const u8,
    };

    /// notify the source-side available actions
    pub const SourceActions = struct {
      source_actions: wl_data_device_manager.DndAction,
    };

    /// notify the selected action
    pub const Action = struct {
      dnd_action: wl_data_device_manager.DndAction,
    };
  };

  pub fn event_decode(conn: *wire.Connection, opcode: u16, payload: []const u32) wire.Error!Event {
    _ = conn;
    var reader: wire.Reader = .{ .payload = payload };
    switch (opcode) {
      0 => return .{ .offer = .{
        .mime_type = try reader.string(),
      } },
      1 => return .{ .source_actions = .{
        .source_actions = @bitCast(try reader.uint()),
      } },
      2 => return .{ .action = .{
        .dnd_action = @bitCast(try reader.uint()),
      } },
      else => return error.InvalidMessage,
    }
  }
};

/// offer to transfer data
pub const wl_data_source = struct {
  pub const NAME = "wl_data_source";
  pub const VERSION = 4;
  pub const INTERFACE: Interface = .wl_data_source;
  pub const Id = enum(u32) { none = 0, _ };

  pub const Error = enum(u32) {
    /// action mask contains invalid values
    invalid_action_mask = 0,
    /// source doesn't accept this request
    invalid_source = 1,
    _,
  };

  /// add an offered mime type
  pub fn offer(conn: *wire.Connection, self: Id, mime_type: []const u8) wire.Error!void {
    const message_size  = 8 + wire.string_size(mime_type);
    const message_start = try conn.message_begin(@intFromEnum(self), 0, message_size, 0);
    conn.put_string(mime_type);
    conn.message_end(message_start);
  }

  /// destroy the data source
  pub fn destroy(conn: *wire.Connection, self: Id) wire.Error!void {
    const message_size  = 8;
    const message_start = try conn.message_begin(@intFromEnum(self), 1, message_size, 0);
    conn.message_end(message_start);
    conn.object_destroy(@intFromEnum(self));
  }

  /// set the available drag-and-drop actions
  pub fn set_actions(
    conn: *wire.Connection,
    self: Id,
    dnd_actions: wl_data_device_manager.DndAction,
  ) wire.Error!void {
    const message_size  = 12;
    const message_start = try conn.message_begin(@intFromEnum(self), 2, message_size, 0);
    conn.put_uint(@bitCast(dnd_actions));
    conn.message_end(message_start);
  }

  pub const EventOpcode = enum(u16) {
    target             = 0,
    send               = 1,
    cancelled          = 2,
    dnd_drop_performed = 3,
    dnd_finished       = 4,
    action             = 5,
  };

  pub const Event = union(EventOpcode) {
    target: Event.Target,
    send: Event.Send,
    cancelled: Event.Cancelled,
    dnd_drop_performed: Event.DndDropPerformed,
    dnd_finished: Event.DndFinished,
    action: Event.Action,

    /// a target accepts an offered mime type
    pub const Target = struct {
      mime_type: ?[]const u8,
    };

    /// send the data
    pub const Send = struct {
      mime_type: []const u8,
      fd: std.os.linux.fd_t,
    };

    /// selection was cancelled
    pub const Cancelled = struct {};

    /// the drag-and-drop operation physically finished
    pub const DndDropPerformed = struct {};

    /// the drag-and-drop operation concluded
    pub const DndFinished = struct {};

    /// notify the selected action
    pub const Action = struct {
      dnd_action: wl_data_device_manager.DndAction,
    };
  };

  pub fn event_decode(conn: *wire.Connection, opcode: u16, payload: []const u32) wire.Error!Event {
    var reader: wire.Reader = .{ .payload = payload };
    switch (opcode) {
      0 => return .{ .target = .{
        .mime_type = try reader.string_optional(),
      } },
      1 => return .{ .send = .{
        .mime_type = try reader.string(),
        .fd        = try conn.fd_take(),
      } },
      2 => return .{ .cancelled = .{} },
      3 => return .{ .dnd_drop_performed = .{} },
      4 => return .{ .dnd_finished = .{} },
      5 => return .{ .action = .{
        .dnd_action = @bitCast(try reader.uint()),
      } },
      else => return error.InvalidMessage,
    }
  }
};

/// data transfer device
pub const wl_data_device = struct {
  pub const NAME = "wl_data_device";
  pub const VERSION = 4;
  pub const INTERFACE: Interface = .wl_data_device;
  pub const Id = enum(u32) { none = 0, _ };

  pub const Error = enum(u32) {
    /// given wl_surface has another role
    role = 0,
    /// source has already been used
    used_source = 1,
    _,
  };

  /// start drag-and-drop operation
  pub fn start_drag(
    conn: *wire.Connection,
    self: Id,
    source: wl_data_source.Id,
    origin: wl_surface.Id,
    icon: wl_surface.Id,
    serial: u32,
  ) wire.Error!void {
    const message_size  = 24;
    const message_start = try conn.message_begin(@intFromEnum(self), 0, message_size, 0);
    conn.put_uint(@intFromEnum(source));
    conn.put_uint(@intFromEnum(origin));
    conn.put_uint(@intFromEnum(icon));
    conn.put_uint(serial);
    conn.message_end(message_start);
  }

  /// copy data to the selection
  pub fn set_selection(
    conn: *wire.Connection,
    self: Id,
    source: wl_data_source.Id,
    serial: u32,
  ) wire.Error!void {
    const message_size  = 16;
    const message_start = try conn.message_begin(@intFromEnum(self), 1, message_size, 0);
    conn.put_uint(@intFromEnum(source));
    conn.put_uint(serial);
    conn.message_end(message_start);
  }

  /// destroy data device
  pub fn release(conn: *wire.Connection, self: Id) wire.Error!void {
    const message_size  = 8;
    const message_start = try conn.message_begin(@intFromEnum(self), 2, message_size, 0);
    conn.message_end(message_start);
    conn.object_destroy(@intFromEnum(self));
  }

  pub const EventOpcode = enum(u16) {
    data_offer = 0,
    enter      = 1,
    leave      = 2,
    motion     = 3,
    drop       = 4,
    selection  = 5,
  };

  pub const Event = union(EventOpcode) {
    data_offer: Event.DataOffer,
    enter: Event.Enter,
    leave: Event.Leave,
    motion: Event.Motion,
    drop: Event.Drop,
    selection: Event.Selection,

    /// introduce a new wl_data_offer
    pub const DataOffer = struct {
      id: wl_data_offer.Id,
    };

    /// initiate drag-and-drop session
    pub const Enter = struct {
      serial: u32,
      surface: wl_surface.Id,
      x: wire.Fixed,
      y: wire.Fixed,
      id: wl_data_offer.Id,
    };

    /// end drag-and-drop session
    pub const Leave = struct {};

    /// drag-and-drop session motion
    pub const Motion = struct {
      time: u32,
      x: wire.Fixed,
      y: wire.Fixed,
    };

    /// end drag-and-drop session successfully
    pub const Drop = struct {};

    /// advertise new selection
    pub const Selection = struct {
      id: wl_data_offer.Id,
    };
  };

  pub fn event_decode(conn: *wire.Connection, opcode: u16, payload: []const u32) wire.Error!Event {
    var reader: wire.Reader = .{ .payload = payload };
    switch (opcode) {
      0 => return .{ .data_offer = .{
        .id = try object_new_server(conn, try reader.uint(), wl_data_offer),
      } },
      1 => return .{ .enter = .{
        .serial  = try reader.uint(),
        .surface = @enumFromInt(try reader.uint()),
        .x       = @enumFromInt(@as(i32, @bitCast(try reader.uint()))),
        .y       = @enumFromInt(@as(i32, @bitCast(try reader.uint()))),
        .id      = @enumFromInt(try reader.uint()),
      } },
      2 => return .{ .leave = .{} },
      3 => return .{ .motion = .{
        .time = try reader.uint(),
        .x    = @enumFromInt(@as(i32, @bitCast(try reader.uint()))),
        .y    = @enumFromInt(@as(i32, @bitCast(try reader.uint()))),
      } },
      4 => return .{ .drop = .{} },
      5 => return .{ .selection = .{
        .id = @enumFromInt(try reader.uint()),
      } },
      else => return error.InvalidMessage,
    }
  }
};

