      name: []const u8,
    };
  };

  pub fn event_decode(conn: *wire.Connection, opcode: u16, payload: []const u32) wire.Error!Event {
    _ = conn;
    var reader: wire.Reader = .{ .payload = payload };
    switch (opcode) {
      0 => return .{ .capabilities = .{
        .capabilities = @bitCast(try reader.uint()),
      } },
      1 => return .{ .name = .{
        .name = try reader.string(),
      } },
      else => return error.InvalidMessage,
    }
  }
};

/// pointer input device
pub const wl_pointer = struct {
  pub const NAME = "wl_pointer";
  pub const VERSION = 11;
  pub const INTERFACE: Interface = .wl_pointer;
  pub const Id = enum(u32) { none = 0, _ };

  pub const Error = enum(u32) {
    /// given wl_surface has another role
    role = 0,
    _,
  };

  pub const ButtonState = enum(u32) {
    /// the button is not pressed
    released = 0,
    /// the button is pressed
    pressed = 1,
    _,
  };

  pub const Axis = enum(u32) {
    /// vertical axis
    vertical_scroll = 0,
    /// horizontal axis
    horizontal_scroll = 1,
    _,
  };

  pub const AxisSource = enum(u32) {
    /// a physical wheel rotation
    wheel = 0,
    /// finger on a touch surface
    finger = 1,
    /// continuous coordinate space
    continuous = 2,
    /// a physical wheel tilt
    wheel_tilt = 3,
    _,
  };

  pub const AxisRelativeDirection = enum(u32) {
    /// physical motion matches axis direction
    identical = 0,
    /// physical motion is the inverse of the axis direction
    inverted = 1,
    _,
  };

  /// set the pointer surface
  pub fn set_cursor(
    conn: *wire.Connection,
    self: Id,
    serial: u32,
    surface: wl_surface.Id,
    hotspot_x: i32,
    hotspot_y: i32,
  ) wire.Error!void {
    const message_size  = 24;
    const message_start = try conn.message_begin(@intFromEnum(self), 0, message_size, 0);
    conn.put_uint(serial);
    conn.put_uint(@intFromEnum(surface));
    conn.put_uint(@bitCast(hotspot_x));
    conn.put_uint(@bitCast(hotspot_y));
    conn.message_end(message_start);
  }

  /// release the pointer object
  pub fn release(conn: *wire.Connection, self: Id) wire.Error!void {
    const message_size  = 8;
    const message_start = try conn.message_begin(@intFromEnum(self), 1, message_size, 0);
    conn.message_end(message_start);
    conn.object_destroy(@intFromEnum(self));
  }

  pub const EventOpcode = enum(u16) {
    enter                   = 0,
    leave                   = 1,
    motion                  = 2,
    button                  = 3,
    axis                    = 4,
    frame                   = 5,
    axis_source             = 6,
    axis_stop               = 7,
    axis_discrete           = 8,
    axis_value120           = 9,
    axis_relative_direction = 10,
    warp                    = 11,
  };

  pub const Event = union(EventOpcode) {
    enter: Event.Enter,
    leave: Event.Leave,
    motion: Event.Motion,
    button: Event.Button,
    axis: Event.Axis,
    frame: Event.Frame,
    axis_source: Event.AxisSource,
    axis_stop: Event.AxisStop,
    axis_discrete: Event.AxisDiscrete,
    axis_value120: Event.AxisValue120,
    axis_relative_direction: Event.AxisRelativeDirection,
    warp: Event.Warp,

    /// enter event
    pub const Enter = struct {
      serial: u32,
      surface: wl_surface.Id,
      surface_x: wire.Fixed,
      surface_y: wire.Fixed,
    };

    /// leave event
    pub const Leave = struct {
      serial: u32,
      surface: wl_surface.Id,
    };

    /// pointer motion event
    pub const Motion = struct {
      time: u32,
      surface_x: wire.Fixed,
      surface_y: wire.Fixed,
    };

    /// pointer button event
    pub const Button = struct {
      serial: u32,
      time: u32,
      button: u32,
      state: wl_pointer.ButtonState,
    };

    /// axis event
    pub const Axis = struct {
      time: u32,
      axis: wl_pointer.Axis,
      value: wire.Fixed,
    };

    /// end of a pointer event sequence
    pub const Frame = struct {};

    /// axis source event
    pub const AxisSource = struct {
      axis_source: wl_pointer.AxisSource,
    };

    /// axis stop event
    pub const AxisStop = struct {
      time: u32,
      axis: wl_pointer.Axis,
    };

    /// axis click event
    pub const AxisDiscrete = struct {
      axis: wl_pointer.Axis,
      discrete: i32,
    };

    /// axis high-resolution scroll event
    pub const AxisValue120 = struct {
      axis: wl_pointer.Axis,
      value120: i32,
    };

    /// axis relative physical direction event
    pub const AxisRelativeDirection = struct {
      axis: wl_pointer.Axis,
      direction: wl_pointer.AxisRelativeDirection,
    };

    /// pointer warp event
    pub const Warp = struct {
      surface_x: wire.Fixed,
      surface_y: wire.Fixed,
    };
  };

  pub fn event_decode(conn: *wire.Connection, opcode: u16, payload: []const u32) wire.Error!Event {
    _ = conn;
    var reader: wire.Reader = .{ .payload = payload };
    switch (opcode) {
      0 => return .{ .enter = .{
        .serial    = try reader.uint(),
        .surface   = @enumFromInt(try reader.uint()),
        .surface_x = @enumFromInt(@as(i32, @bitCast(try reader.uint()))),
        .surface_y = @enumFromInt(@as(i32, @bitCast(try reader.uint()))),
      } },
      1 => return .{ .leave = .{
        .serial  = try reader.uint(),
        .surface = @enumFromInt(try reader.uint()),
      } },
      2 => return .{ .motion = .{
        .time      = try reader.uint(),
        .surface_x = @enumFromInt(@as(i32, @bitCast(try reader.uint()))),
        .surface_y = @enumFromInt(@as(i32, @bitCast(try reader.uint()))),
      } },
      3 => return .{ .button = .{
        .serial = try reader.uint(),
        .time   = try reader.uint(),
        .button = try reader.uint(),
        .state  = @enumFromInt(try reader.uint()),
      } },
      4 => return .{ .axis = .{
        .time  = try reader.uint(),
        .axis  = @enumFromInt(try reader.uint()),
        .value = @enumFromInt(@as(i32, @bitCast(try reader.uint()))),
      } },
      5 => return .{ .frame = .{} },
      6 => return .{ .axis_source = .{
        .axis_source = @enumFromInt(try reader.uint()),
      } },
      7 => return .{ .axis_stop = .{
        .time = try reader.uint(),
        .axis = @enumFromInt(try reader.uint()),
      } },
      8 => return .{ .axis_discrete = .{
        .axis     = @enumFromInt(try reader.uint()),
        .discrete = @bitCast(try reader.uint()),
      } },
      9 => return .{ .axis_value120 = .{
        .axis     = @enumFromInt(try reader.uint()),
        .value120 = @bitCast(try reader.uint()),
      } },
      10 => return .{ .axis_relative_direction = .{
        .axis      = @enumFromInt(try reader.uint()),
        .direction = @enumFromInt(try reader.uint()),
      } },
      11 => return .{ .warp = .{
        .surface_x = @enumFromInt(@as(i32, @bitCast(try reader.uint()))),
        .surface_y = @enumFromInt(@as(i32, @bitCast(try reader.uint()))),
      } },
      else => return error.InvalidMessage,
    }
  }
};

/// keyboard input device
pub const wl_keyboard = struct {
  pub const NAME = "wl_keyboard";
  pub const VERSION = 11;
  pub const INTERFACE: Interface = .wl_keyboard;
  pub const Id = enum(u32) { none = 0, _ };

  pub const KeymapFormat = enum(u32) {
    /// no keymap; client must understand how to interpret the raw keycode
    no_keymap = 0,
    /// libxkbcommon compatible, null-terminated string; to determine the xkb keycode, clients must add 8 to
    /// the key event keycode
    xkb_v1 = 1,
    _,
  };

  pub const KeyState = enum(u32) {
    /// key is not pressed
    released = 0,
    /// key is pressed
    pressed = 1,
    /// key was repeated
    repeated = 2,
    _,
  };

  /// release the keyboard object
  pub fn release(conn: *wire.Connection, self: Id) wire.Error!void {
    const message_size  = 8;
    const message_start = try conn.message_begin(@intFromEnum(self), 0, message_size, 0);
    conn.message_end(message_start);
    conn.object_destroy(@intFromEnum(self));
  }

  pub const EventOpcode = enum(u16) {
    keymap      = 0,
    enter       = 1,
    leave       = 2,
    key         = 3,
    modifiers   = 4,
    repeat_info = 5,
  };

  pub const Event = union(EventOpcode) {
    keymap: Event.Keymap,
    enter: Event.Enter,
    leave: Event.Leave,
    key: Event.Key,
    modifiers: Event.Modifiers,
    repeat_info: Event.RepeatInfo,

    /// keyboard mapping
    pub const Keymap = struct {
      format: wl_keyboard.KeymapFormat,
      fd: std.os.linux.fd_t,
      size: u32,
    };

    /// enter event
    pub const Enter = struct {
      serial: u32,
      surface: wl_surface.Id,
      keys: []const u8,
    };

    /// leave event
    pub const Leave = struct {
      serial: u32,
      surface: wl_surface.Id,
    };

    /// key event
    pub const Key = struct {
      serial: u32,
      time: u32,
      key: u32,
      state: wl_keyboard.KeyState,
    };

    /// modifier and group state
    pub const Modifiers = struct {
      serial: u32,
      mods_depressed: u32,
      mods_latched: u32,
      mods_locked: u32,
      group: u32,
    };

    /// repeat rate and delay
    pub const RepeatInfo = struct {
      rate: i32,
      delay: i32,
    };
  };

  pub fn event_decode(conn: *wire.Connection, opcode: u16, payload: []const u32) wire.Error!Event {
    var reader: wire.Reader = .{ .payload = payload };
    switch (opcode) {
      0 => return .{ .keymap = .{
        .format = @enumFromInt(try reader.uint()),
        .fd     = try conn.fd_take(),
        .size   = try reader.uint(),
      } },
      1 => return .{ .enter = .{
        .serial  = try reader.uint(),
        .surface = @enumFromInt(try reader.uint()),
        .keys    = try reader.array(),
      } },
      2 => return .{ .leave = .{
        .serial  = try reader.uint(),
        .surface = @enumFromInt(try reader.uint()),
      } },
      3 => return .{ .key = .{
        .serial = try reader.uint(),
        .time   = try reader.uint(),
        .key    = try reader.uint(),
        .state  = @enumFromInt(try reader.uint()),
      } },
      4 => return .{ .modifiers = .{
        .serial         = try reader.uint(),
        .mods_depressed = try reader.uint(),
        .mods_latched   = try reader.uint(),
        .mods_locked    = try reader.uint(),
        .group          = try reader.uint(),
      } },
      5 => return .{ .repeat_info = .{
        .rate  = @bitCast(try reader.uint()),
        .delay = @bitCast(try reader.uint()),
      } },
      else => return error.InvalidMessage,
    }
  }
};

/// touchscreen input device
pub const wl_touch = struct {
  pub const NAME = "wl_touch";
  pub const VERSION = 11;
  pub const INTERFACE: Interface = .wl_touch;
  pub const Id = enum(u32) { none = 0, _ };

  /// release the touch object
  pub fn release(conn: *wire.Connection, self: Id) wire.Error!void {
    const message_size  = 8;
    const message_start = try conn.message_begin(@intFromEnum(self), 0, message_size, 0);
    conn.message_end(message_start);
    conn.object_destroy(@intFromEnum(self));
  }

  pub const EventOpcode = enum(u16) {
    down        = 0,
    up          = 1,
    motion      = 2,
    frame       = 3,
    cancel      = 4,
    shape       = 5,
    orientation = 6,
  };

  pub const Event = union(EventOpcode) {
    down: Event.Down,
    up: Event.Up,
    motion: Event.Motion,
    frame: Event.Frame,
    cancel: Event.Cancel,
    shape: Event.Shape,
    orientation: Event.Orientation,

    /// touch down event and beginning of a touch sequence
    pub const Down = struct {
      serial: u32,
      time: u32,
      surface: wl_surface.Id,
      id: i32,
      x: wire.Fixed,
      y: wire.Fixed,
    };

    /// end of a touch event sequence
    pub const Up = struct {
      serial: u32,
      time: u32,
      id: i32,
    };

    /// update of touch point coordinates
    pub const Motion = struct {
      time: u32,
      id: i32,
      x: wire.Fixed,
      y: wire.Fixed,
    };

    /// end of touch frame event
    pub const Frame = struct {};

    /// touch session cancelled
    pub const Cancel = struct {};

    /// update shape of touch point
    pub const Shape = struct {
      id: i32,
      major: wire.Fixed,
      minor: wire.Fixed,
    };

    /// update orientation of touch point
    pub const Orientation = struct {
      id: i32,
      orientation: wire.Fixed,
    };
  };

  pub fn event_decode(conn: *wire.Connection, opcode: u16, payload: []const u32) wire.Error!Event {
    _ = conn;
    var reader: wire.Reader = .{ .payload = payload };
    switch (opcode) {
      0 => return .{ .down = .{
        .serial  = try reader.uint(),
        .time    = try reader.uint(),
        .surface = @enumFromInt(try reader.uint()),
        .id      = @bitCast(try reader.uint()),
        .x       = @enumFromInt(@as(i32, @bitCast(try reader.uint()))),
        .y       = @enumFromInt(@as(i32, @bitCast(try reader.uint()))),
      } },
      1 => return .{ .up = .{
        .serial = try reader.uint(),
        .time   = try reader.uint(),
        .id     = @bitCast(try reader.uint()),
      } },
      2 => return .{ .motion = .{
        .time = try reader.uint(),
        .id   = @bitCast(try reader.uint()),
        .x    = @enumFromInt(@as(i32, @bitCast(try reader.uint()))),
        .y    = @enumFromInt(@as(i32, @bitCast(try reader.uint()))),
      } },
      3 => return .{ .frame = .{} },
      4 => return .{ .cancel = .{} },
      5 => return .{ .shape = .{
        .id    = @bitCast(try reader.uint()),
        .major = @enumFromInt(@as(i32, @bitCast(try reader.uint()))),
        .minor = @enumFromInt(@as(i32, @bitCast(try reader.uint()))),
      } },
      6 => return .{ .orientation = .{
        .id          = @bitCast(try reader.uint()),
        .orientation = @enumFromInt(@as(i32, @bitCast(try reader.uint()))),
      } },
      else => return error.InvalidMessage,
    }
  }
};

