    /// horizontal BGR
    horizontal_bgr = 3,
    /// vertical RGB
    vertical_rgb = 4,
    /// vertical BGR
    vertical_bgr = 5,
    _,
  };

  pub const Transform = enum(u32) {
    /// no transform
    normal = 0,
    /// 90 degrees counter-clockwise
    @"90" = 1,
    /// 180 degrees counter-clockwise
    @"180" = 2,
    /// 270 degrees counter-clockwise
    @"270" = 3,
    /// 180 degree flip around a vertical axis
    flipped = 4,
    /// flip and rotate 90 degrees counter-clockwise
    flipped_90 = 5,
    /// flip and rotate 180 degrees counter-clockwise
    flipped_180 = 6,
    /// flip and rotate 270 degrees counter-clockwise
    flipped_270 = 7,
    _,
  };

  pub const Mode = packed struct(u32) {
    /// indicates this is the current mode
    current: bool = false,
    /// indicates this is the preferred mode
    preferred: bool = false,
    _2: u30 = 0,
  };

  /// release the output object
  pub fn release(conn: *wire.Connection, self: Id) wire.Error!void {
    const message_size  = 8;
    const message_start = try conn.message_begin(@intFromEnum(self), 0, message_size, 0);
    conn.message_end(message_start);
    conn.object_destroy(@intFromEnum(self));
  }

  pub const EventOpcode = enum(u16) {
    geometry    = 0,
    mode        = 1,
    done        = 2,
    scale       = 3,
    name        = 4,
    description = 5,
  };

  pub const Event = union(EventOpcode) {
    geometry: Event.Geometry,
    mode: Event.Mode,
    done: Event.Done,
    scale: Event.Scale,
    name: Event.Name,
    description: Event.Description,

    /// properties of the output
    pub const Geometry = struct {
      x: i32,
      y: i32,
      physical_width: i32,
      physical_height: i32,
      subpixel: wl_output.Subpixel,
      make: []const u8,
      model: []const u8,
      transform: wl_output.Transform,
    };

    /// advertise available modes for the output
    pub const Mode = struct {
      flags: wl_output.Mode,
      width: i32,
      height: i32,
      refresh: i32,
    };

    /// sent all information about output
    pub const Done = struct {};

    /// output scaling properties
    pub const Scale = struct {
      factor: i32,
    };

    /// name of this output
    pub const Name = struct {
      name: []const u8,
    };

    /// human-readable description of this output
    pub const Description = struct {
      description: []const u8,
    };
  };

  pub fn event_decode(conn: *wire.Connection, opcode: u16, payload: []const u32) wire.Error!Event {
    _ = conn;
    var reader: wire.Reader = .{ .payload = payload };
    switch (opcode) {
      0 => return .{ .geometry = .{
        .x               = @bitCast(try reader.uint()),
        .y               = @bitCast(try reader.uint()),
        .physical_width  = @bitCast(try reader.uint()),
        .physical_height = @bitCast(try reader.uint()),
        .subpixel        = @enumFromInt(try reader.uint()),
        .make            = try reader.string(),
        .model           = try reader.string(),
        .transform       = @enumFromInt(try reader.uint()),
      } },
      1 => return .{ .mode = .{
        .flags   = @bitCast(try reader.uint()),
        .width   = @bitCast(try reader.uint()),
        .height  = @bitCast(try reader.uint()),
        .refresh = @bitCast(try reader.uint()),
      } },
      2 => return .{ .done = .{} },
      3 => return .{ .scale = .{
        .factor = @bitCast(try reader.uint()),
      } },
      4 => return .{ .name = .{
        .name = try reader.string(),
      } },
      5 => return .{ .description = .{
        .description = try reader.string(),
      } },
      else => return error.InvalidMessage,
    }
  }
};

