    const message_size  = 8;
    const message_start = try conn.message_begin(@intFromEnum(self), 13, message_size, 0);
    conn.message_end(message_start);
  }

  pub const EventOpcode = enum(u16) {
    configure        = 0,
    close            = 1,
    configure_bounds = 2,
    wm_capabilities  = 3,
  };

  pub const Event = union(EventOpcode) {
    configure: Event.Configure,
    close: Event.Close,
    configure_bounds: Event.ConfigureBounds,
    wm_capabilities: Event.WmCapabilities,

    /// suggest a surface change
    pub const Configure = struct {
      width: i32,
      height: i32,
      states: []const u8,
    };

    /// surface wants to be closed
    pub const Close = struct {};

    /// recommended window geometry bounds
    pub const ConfigureBounds = struct {
      width: i32,
      height: i32,
    };

    /// compositor capabilities
    pub const WmCapabilities = struct {
      capabilities: []const u8,
    };
  };

  pub fn event_decode(conn: *wire.Connection, opcode: u16, payload: []const u32) wire.Error!Event {
    _ = conn;
    var reader: wire.Reader = .{ .payload = payload };
    switch (opcode) {
      0 => return .{ .configure = .{
        .width  = @bitCast(try reader.uint()),
        .height = @bitCast(try reader.uint()),
        .states = try reader.array(),
      } },
      1 => return .{ .close = .{} },
      2 => return .{ .configure_bounds = .{
        .width  = @bitCast(try reader.uint()),
        .height = @bitCast(try reader.uint()),
      } },
      3 => return .{ .wm_capabilities = .{
        .capabilities = try reader.array(),
      } },
      else => return error.InvalidMessage,
    }
  }
};

