  pub const Id = enum(u32) { none = 0, _ };

  pub const Error = enum(u32) {
    /// the zwp_linux_buffer_params_v1 object has already been used to create a wl_buffer
    already_used = 0,
    /// plane index out of bounds
    plane_idx = 1,
    /// the plane index was already set
    plane_set = 2,
    /// missing or too many planes to create a buffer
    incomplete = 3,
    /// format not supported
    invalid_format = 4,
    /// invalid width or height
    invalid_dimensions = 5,
    /// offset + stride * height goes out of dmabuf bounds
    out_of_bounds = 6,
    /// invalid wl_buffer resulted from importing dmabufs via the create_immed request on given buffer_params
    invalid_wl_buffer = 7,
    /// an array with mismatching size for a dev_t was used
    invalid_dev_t_size = 8,
    _,
  };

  pub const Flags = packed struct(u32) {
    /// contents are y-inverted
    y_invert: bool = false,
    /// content is interlaced
    interlaced: bool = false,
    /// bottom field first
    bottom_first: bool = false,
    _3: u29 = 0,
  };

  /// delete this object, used or not
  pub fn destroy(conn: *wire.Connection, self: Id) wire.Error!void {
    const message_size  = 8;
    const message_start = try conn.message_begin(@intFromEnum(self), 0, message_size, 0);
    conn.message_end(message_start);
    conn.object_destroy(@intFromEnum(self));
  }

  /// add a dmabuf to the temporary set
  pub fn add(
    conn: *wire.Connection,
    self: Id,
    fd: std.os.linux.fd_t,
    plane_idx: u32,
    offset: u32,
    stride: u32,
    modifier_hi: u32,
    modifier_lo: u32,
  ) wire.Error!void {
    const message_size  = 28;
    const message_start = try conn.message_begin(@intFromEnum(self), 1, message_size, 1);
    conn.put_fd(fd);
    conn.put_uint(plane_idx);
    conn.put_uint(offset);
    conn.put_uint(stride);
    conn.put_uint(modifier_hi);
    conn.put_uint(modifier_lo);
    conn.message_end(message_start);
  }

  /// create a wl_buffer from the given dmabufs
  pub fn create(
    conn: *wire.Connection,
    self: Id,
    width: i32,
    height: i32,
    format: u32,
    flags: zwp_linux_buffer_params_v1.Flags,
  ) wire.Error!void {
    const message_size  = 24;
    const message_start = try conn.message_begin(@intFromEnum(self), 2, message_size, 0);
    conn.put_uint(@bitCast(width));
    conn.put_uint(@bitCast(height));
    conn.put_uint(format);
    conn.put_uint(@bitCast(flags));
    conn.message_end(message_start);
  }

  /// immediately create a wl_buffer from the given dmabufs
  pub fn create_immed(
    conn: *wire.Connection,
    self: Id,
    width: i32,
    height: i32,
    format: u32,
    flags: zwp_linux_buffer_params_v1.Flags,
  ) wire.Error!wl_buffer.Id {
    const buffer_id     = try object_new(conn, wl_buffer);
    const message_size  = 28;
    const message_start = try conn.message_begin(@intFromEnum(self), 3, message_size, 0);
    conn.put_uint(@intFromEnum(buffer_id));
    conn.put_uint(@bitCast(width));
    conn.put_uint(@bitCast(height));
    conn.put_uint(format);
    conn.put_uint(@bitCast(flags));
    conn.message_end(message_start);
    return buffer_id;
  }

  /// set the target device of the wl_buffer
  pub fn set_sampling_device(conn: *wire.Connection, self: Id, device: []const u8) wire.Error!void {
    const message_size  = 8 + wire.array_size(device);
    const message_start = try conn.message_begin(@intFromEnum(self), 4, message_size, 0);
    conn.put_array(device);
    conn.message_end(message_start);
  }

  pub const EventOpcode = enum(u16) {
    created = 0,
    failed  = 1,
  };

  pub const Event = union(EventOpcode) {
    created: Event.Created,
    failed: Event.Failed,

    /// buffer creation succeeded
    pub const Created = struct {
      buffer: wl_buffer.Id,
    };

    /// buffer creation failed
    pub const Failed = struct {};
  };

  pub fn event_decode(conn: *wire.Connection, opcode: u16, payload: []const u32) wire.Error!Event {
    var reader: wire.Reader = .{ .payload = payload };
    switch (opcode) {
      0 => return .{ .created = .{
        .buffer = try object_new_server(conn, try reader.uint(), wl_buffer),
      } },
      1 => return .{ .failed = .{} },
      else => return error.InvalidMessage,
    }
  }
};

/// dmabuf feedback
pub const zwp_linux_dmabuf_feedback_v1 = struct {
  pub const NAME = "zwp_linux_dmabuf_feedback_v1";
  pub const VERSION = 6;
  pub const INTERFACE: Interface = .zwp_linux_dmabuf_feedback_v1;
  pub const Id = enum(u32) { none = 0, _ };

  pub const TrancheFlags = packed struct(u32) {
    /// direct scan-out tranche
    scanout: bool = false,
    /// sampling tranche
    sampling: bool = false,
    _2: u30 = 0,
  };

  /// destroy the feedback object
  pub fn destroy(conn: *wire.Connection, self: Id) wire.Error!void {
    const message_size  = 8;
    const message_start = try conn.message_begin(@intFromEnum(self), 0, message_size, 0);
    conn.message_end(message_start);
    conn.object_destroy(@intFromEnum(self));
  }

  pub const EventOpcode = enum(u16) {
    done                  = 0,
    format_table          = 1,
    main_device           = 2,
    tranche_done          = 3,
    tranche_target_device = 4,
    tranche_formats       = 5,
    tranche_flags         = 6,
  };

  pub const Event = union(EventOpcode) {
    done: Event.Done,
    format_table: Event.FormatTable,
    main_device: Event.MainDevice,
    tranche_done: Event.TrancheDone,
    tranche_target_device: Event.TrancheTargetDevice,
    tranche_formats: Event.TrancheFormats,
    tranche_flags: Event.TrancheFlags,

    /// all feedback has been sent
    pub const Done = struct {};

    /// format and modifier table
    pub const FormatTable = struct {
      fd: std.os.linux.fd_t,
      size: u32,
    };

    /// preferred main device
    pub const MainDevice = struct {
      device: []const u8,
    };

    /// a preference tranche has been sent
    pub const TrancheDone = struct {};

    /// target device
    pub const TrancheTargetDevice = struct {
      device: []const u8,
    };

    /// supported buffer format modifiers
    pub const TrancheFormats = struct {
      indices: []const u8,
    };

    /// tranche flags
    pub const TrancheFlags = struct {
      flags: zwp_linux_dmabuf_feedback_v1.TrancheFlags,
    };
  };

  pub fn event_decode(conn: *wire.Connection, opcode: u16, payload: []const u32) wire.Error!Event {
    var reader: wire.Reader = .{ .payload = payload };
    switch (opcode) {
      0 => return .{ .done = .{} },
      1 => return .{ .format_table = .{
        .fd   = try conn.fd_take(),
        .size = try reader.uint(),
      } },
      2 => return .{ .main_device = .{
        .device = try reader.array(),
      } },
      3 => return .{ .tranche_done = .{} },
      4 => return .{ .tranche_target_device = .{
        .device = try reader.array(),
      } },
      5 => return .{ .tranche_formats = .{
        .indices = try reader.array(),
      } },
      6 => return .{ .tranche_flags = .{
        .flags = @bitCast(try reader.uint()),
      } },
      else => return error.InvalidMessage,
    }
  }
};

