  }

  pub const EventOpcode = enum(u16) {
    type              = 0,
    hardware_serial   = 1,
    hardware_id_wacom = 2,
    capability        = 3,
    done              = 4,
    removed           = 5,
    proximity_in      = 6,
    proximity_out     = 7,
    down              = 8,
    up                = 9,
    motion            = 10,
    pressure          = 11,
    distance          = 12,
    tilt              = 13,
    rotation          = 14,
    slider            = 15,
    wheel             = 16,
    button            = 17,
    frame             = 18,
  };

  pub const Event = union(EventOpcode) {
    type: Event.Type,
    hardware_serial: Event.HardwareSerial,
    hardware_id_wacom: Event.HardwareIdWacom,
    capability: Event.Capability,
    done: Event.Done,
    removed: Event.Removed,
    proximity_in: Event.ProximityIn,
    proximity_out: Event.ProximityOut,
    down: Event.Down,
    up: Event.Up,
    motion: Event.Motion,
    pressure: Event.Pressure,
    distance: Event.Distance,
    tilt: Event.Tilt,
    rotation: Event.Rotation,
    slider: Event.Slider,
    wheel: Event.Wheel,
    button: Event.Button,
    frame: Event.Frame,

    /// tool type
    pub const Type = struct {
      tool_type: zwp_tablet_tool_v2.Type,
    };

    /// unique hardware serial number of the tool
    pub const HardwareSerial = struct {
      hardware_serial_hi: u32,
      hardware_serial_lo: u32,
    };

    /// hardware id notification in Wacom's format
    pub const HardwareIdWacom = struct {
      hardware_id_hi: u32,
      hardware_id_lo: u32,
    };

    /// tool capability notification
    pub const Capability = struct {
      capability: zwp_tablet_tool_v2.Capability,
    };

    /// tool description events sequence complete
    pub const Done = struct {};

    /// tool removed
    pub const Removed = struct {};

    /// proximity in event
    pub const ProximityIn = struct {
      serial: u32,
      tablet: zwp_tablet_v2.Id,
      surface: wl_surface.Id,
    };

    /// proximity out event
    pub const ProximityOut = struct {};

    /// tablet tool is making contact
    pub const Down = struct {
      serial: u32,
    };

    /// tablet tool is no longer making contact
    pub const Up = struct {};

    /// motion event
    pub const Motion = struct {
      x: wire.Fixed,
      y: wire.Fixed,
    };

    /// pressure change event
    pub const Pressure = struct {
      pressure: u32,
    };

    /// distance change event
    pub const Distance = struct {
      distance: u32,
    };

    /// tilt change event
    pub const Tilt = struct {
      tilt_x: wire.Fixed,
      tilt_y: wire.Fixed,
    };

    /// z-rotation change event
    pub const Rotation = struct {
      degrees: wire.Fixed,
    };

    /// Slider position change event
    pub const Slider = struct {
      position: i32,
    };

    /// Wheel delta event
    pub const Wheel = struct {
      degrees: wire.Fixed,
      clicks: i32,
    };

    /// button event
    pub const Button = struct {
      serial: u32,
      button: u32,
      state: zwp_tablet_tool_v2.ButtonState,
    };

    /// frame event
    pub const Frame = struct {
      time: u32,
    };
  };

  pub fn event_decode(conn: *wire.Connection, opcode: u16, payload: []const u32) wire.Error!Event {
    _ = conn;
    var reader: wire.Reader = .{ .payload = payload };
    switch (opcode) {
      0 => return .{ .type = .{
        .tool_type = @enumFromInt(try reader.uint()),
      } },
      1 => return .{ .hardware_serial = .{
        .hardware_serial_hi = try reader.uint(),
        .hardware_serial_lo = try reader.uint(),
      } },
      2 => return .{ .hardware_id_wacom = .{
        .hardware_id_hi = try reader.uint(),
        .hardware_id_lo = try reader.uint(),
      } },
      3 => return .{ .capability = .{
        .capability = @enumFromInt(try reader.uint()),
      } },
      4 => return .{ .done = .{} },
      5 => return .{ .removed = .{} },
      6 => return .{ .proximity_in = .{
        .serial  = try reader.uint(),
        .tablet  = @enumFromInt(try reader.uint()),
        .surface = @enumFromInt(try reader.uint()),
      } },
      7 => return .{ .proximity_out = .{} },
      8 => return .{ .down = .{
        .serial = try reader.uint(),
      } },
      9 => return .{ .up = .{} },
      10 => return .{ .motion = .{
        .x = @enumFromInt(@as(i32, @bitCast(try reader.uint()))),
        .y = @enumFromInt(@as(i32, @bitCast(try reader.uint()))),
      } },
      11 => return .{ .pressure = .{
        .pressure = try reader.uint(),
      } },
      12 => return .{ .distance = .{
        .distance = try reader.uint(),
      } },
      13 => return .{ .tilt = .{
        .tilt_x = @enumFromInt(@as(i32, @bitCast(try reader.uint()))),
        .tilt_y = @enumFromInt(@as(i32, @bitCast(try reader.uint()))),
      } },
      14 => return .{ .rotation = .{
        .degrees = @enumFromInt(@as(i32, @bitCast(try reader.uint()))),
      } },
      15 => return .{ .slider = .{
        .position = @bitCast(try reader.uint()),
      } },
      16 => return .{ .wheel = .{
        .degrees = @enumFromInt(@as(i32, @bitCast(try reader.uint()))),
        .clicks  = @bitCast(try reader.uint()),
      } },
      17 => return .{ .button = .{
        .serial = try reader.uint(),
        .button = try reader.uint(),
        .state  = @enumFromInt(try reader.uint()),
      } },
      18 => return .{ .frame = .{
        .time = try reader.uint(),
      } },
      else => return error.InvalidMessage,
    }
  }
};

