/// Decodes the next complete received message. Messages for unknown objects are skipped.
pub fn event_next(conn: *wire.Connection) wire.Error!?Message {
  for (0..wire.RECV_MESSAGES_MAX) |_| {
    const message              = try conn.message_next() orelse return null;
    const interface: Interface = @enumFromInt(conn.object_interface(message.id));
    switch (interface) {
      .wl_display => {
        const event = try wl_display.event_decode(conn, message.opcode, message.payload);
        if (event == .delete_id) conn.object_free(event.delete_id.id);
        return .{ .id = message.id, .event = .{ .wl_display = event } };
      },
      .wl_registry => {
        const event = try wl_registry.event_decode(conn, message.opcode, message.payload);
        return .{ .id = message.id, .event = .{ .wl_registry = event } };
      },
      .wl_callback => {
        const event = try wl_callback.event_decode(conn, message.opcode, message.payload);
        return .{ .id = message.id, .event = .{ .wl_callback = event } };
      },
      .wl_shm => {
        const event = try wl_shm.event_decode(conn, message.opcode, message.payload);
        return .{ .id = message.id, .event = .{ .wl_shm = event } };
      },
      .wl_buffer => {
        const event = try wl_buffer.event_decode(conn, message.opcode, message.payload);
        return .{ .id = message.id, .event = .{ .wl_buffer = event } };
      },
      .wl_data_offer => {
        const event = try wl_data_offer.event_decode(conn, message.opcode, message.payload);
